using UnityEngine;

namespace Logistics
{
    /// <summary>All materials the procedural visuals use, generated by Tools ▸ Logistics ▸ Build Materials.</summary>
    [CreateAssetMenu(menuName = "Logistics/Material Library", fileName = "MaterialLibrary")]
    public class MaterialLibrary : ScriptableObject
    {
        [Header("PBR surfaces (Poly Haven, CC0)")]
        public Material asphalt;
        public Material sidewalk;
        public Material lot;
        public Material grass;
        public Material riverbed;
        public Material warehouseWall;
        public Material warehouseRoof;
        public Material brick;
        public Material plaster;
        public Material roofTiles;
        public Material flatRoof;

        [Header("Texture real-world sizes (meters per texture repeat)")]
        public float asphaltMeters = 3f;
        public float sidewalkMeters = 1.8f;
        public float lotMeters = 2f;
        public float grassMeters = 15f;
        public float riverbedMeters = 20f;
        public float warehouseWallMeters = 3f;
        public float warehouseRoofMeters = 2f;
        public float brickMeters = 1.4f;
        public float plasterMeters = 3f;
        public float roofTilesMeters = 6f;
        public float flatRoofMeters = 2.2f;

        [Header("Plain")]
        public Material concrete;
        public Material marking;
        public Material water;
        public Material glass;
        public Material rubber;
        public Material chassis;
        public Material cabPaint;
        public Material darkMetal;
        public Material bark;
        public Material[] foliage = new Material[3];
        public Material headlight;
        public Material brakeOff;
        public Material brakeOn;
        public Material[] cargoPaint = new Material[CargoInfo.Count];
        public Material[] cargoGlow = new Material[CargoInfo.Count];

        [Header("Overlays (unlit)")]
        public Material overlay;
        public Material ghost;
        public Material ringBase;
        public Material ringFill;
        public Material fx;

        public Material Paint(CargoType c) => cargoPaint[(int)c];
        public Material Glow(CargoType c) => cargoGlow[(int)c];
    }
}
